This function useful for tests
```cpp
using ::protobuf_matchers::MakePartialProtoFromAscii;
using ::protobuf_matchers::EqualsProto;

TEST(set_topics, _)
{
	auto [mqClient, dbClient] = testingClients();
	initDB(dbClient);
	auto initSql = "INSERT INTO topic (id, topic) VALUES "
	               "(1, 'tagZ'), (2, 'tagA'), (3, 'TAG')";
	dbClient->query(initSql).get();

	Service service{mqClient, dbClient, 17};
	service.startAcceptingRequests();

	{
		using Method = room::set_topics::Method;
		auto params = MakePartialProtoFromAscii<Method::Params>("room_id: 31 topics: ['tagZ', 'tagA', 'TAG']");
		auto retval = mqClient->call<Method>(params, "31").get();
		EXPECT_THAT(retval, EqualsProto("status: STATUS_CODE_SUCCESS max_num: 17 topics: ['tagZ', 'tagA', 'TAG']"));
	}
	{
		using Method = room::get_topics::Method;
		auto params = MakePartialProtoFromAscii<Method::Params>("room_id: 31");
		auto retval = mqClient->call<Method>(params, "31").get();
		EXPECT_THAT(retval, EqualsProto("max_num: 17 topics: ['tagZ', 'tagA', 'TAG']"));
	}
}
```

